   const all=Store.state.cards.filter(c=>this.matches(c,q)&&!Store.item(c.id).dismissed);
   return {desk:all.filter(c=>this.shelfOf(c)==='desk'),shelved:all.filter(c=>this.shelfOf(c)!=='desk')};
